# backend/agent/kernel package. Generated by scripts/kernel_split_check.py (init-package / move).
# kernel_source(): the facade text followed by every kernel/**/*.py text (except __init__.py)
# in sorted order, for tests that scan the kernel source as text. Stdlib only; it imports no
# kernel module. Text mode, so line endings are universal newlines like read_text().
import os


def kernel_source(encoding="utf-8", errors="replace") -> str:
    here = os.path.dirname(os.path.abspath(__file__))
    paths = [os.path.join(os.path.dirname(here), "agent_kernel.py")]
    found = []
    for dirpath, dirnames, filenames in os.walk(here):
        dirnames[:] = sorted(d for d in dirnames if d != "__pycache__")
        found.extend(os.path.join(dirpath, f) for f in filenames
                     if f.endswith(".py") and f != "__init__.py")
    paths.extend(sorted(found, key=lambda q: os.path.relpath(q, here).replace(os.sep, "/")))
    parts = []
    for path in paths:
        with open(path, "r", encoding=encoding, errors=errors) as fh:
            text = fh.read()
        parts.append(text if (not text or text.endswith("\n")) else text + "\n")
    return "".join(parts)
